/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import { Card, Row, Col, Form, Input, Button, DatePicker, Select, notification } from 'antd'
import StyleWrapper from './index.style'
import { useLoaderContextValue } from '../../../../globalContextProvider/LoaderContext'
import { useProvinceList, useCityList, useBirthCityList, useResetState, useCreateQuote } from '../../../state/teleSalesTeam/hooks/useTeleSales'
import { useError } from '../../../../state/error/hooks/useError'
import moment from 'moment'
import { get, size } from 'lodash'

const { Option } = Select

export function BukalapakLeadGeneration ({ history, ...props }) {
  const [birthplace, setBirthPlace] = useState([])
  const [provinceData, setProvinceData] = useState([])
  const [cityList, setCityList] = useState([])
  const [{ provinceListData, provinceListStatus }, provinceListRequest] = useProvinceList()
  const [{ cityListData, cityListStatus }, cityListRequest] = useCityList()
  const [{ birthPlaceData, birthPlaceStatus }, birthListRequest] = useBirthCityList()
  const [{ bukalapakQuoteData, bukalapakQuoteStatus }, createQuoteRequest] = useCreateQuote()
  const [{ PROVINCE_LIST_LOADER, BIRTH_POLICY_LOADER, CITY_LIST_LOADER, BUKALAPAK_QUOTE_LOADER }] = useLoaderContextValue()

  const [resetTeleSalesTeam] = useResetState()
  const { resetError } = useError()
  const { form } = props
  const { getFieldDecorator, setFieldsValue, resetFields } = form

  useEffect(() => {
    if (birthPlaceStatus === 'success') {
      setBirthPlace(birthPlaceData)
    }
    if (provinceListStatus === 'success') {
      setProvinceData(provinceListData)
    }
    if (cityListStatus === 'success') {
      setCityList(cityListData)
    }

    if (bukalapakQuoteStatus === 'success') {
      notification.success({ message: 'Bukalapak Quote created Successfully' })
      resetTeleSalesTeam(['bukalapakQuoteData', 'bukalapakQuoteStatus'])
      resetError(['BUKALAPAK_QUOTE_ERROR'])
      resetFields()
    }

    if (bukalapakQuoteStatus !== 'success' && bukalapakQuoteStatus !== undefined) {
      notification.error({ message: 'Error in creating Bukalapak Quote' })
      resetTeleSalesTeam(['bukalapakQuoteData', 'bukalapakQuoteStatus'])
      resetError(['BUKALAPAK_QUOTE_ERROR'])
    }

    return () => {
      resetTeleSalesTeam(['birthCityListStatus', 'birthCityListData', 'provinceListData', 'provinceListStatus', 'cityListStatus', 'cityListData'])
    }
  }, [birthPlaceData, provinceListData, cityListData, bukalapakQuoteData])

  useEffect(() => {
    provinceListRequest()
    birthListRequest()
    return () => {
      // resetError(['BUKALAPAK_QUOTE_ERROR'])
    }
  }, [])

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (err) {
        return
      }
      for (const key in values) {
        if (key === 'dob') {
          values = {
            ...values,
            dob: values.dob.format('YYYY-MM-DD')
          }
        }
        if (key === 'payment_verified_date') {
          values = {
            ...values,
            payment_verified_date: values.payment_verified_date.format('YYYY-MM-DD HH:mm:ss')
          }
        }
      }
      values = {
        ...values,
        product: 'health-protection-mega',
        quote_type: 'bukalapak_health_protection_mega',
        package_id: 'A',
        partner: 'bukalapak',
        utm_medium: null,
        utm_source: null,
        utm_campaign: null,
        premium: 600000
      }
      createQuoteRequest({
        body: values
      })
    })
  }

  const checkDobValidator = (rule, value, callback) => {
    const date = new Date()
    const spty = moment(value).format('YYYY-MM-DD').split('-')[0]
    const sptyCurrent = moment(date).format('YYYY-MM-DD').split('-')[0]
    const sptmCurrent = moment(date).format('YYYY-MM-DD').split('-')[1]
    const sptd = moment(value).format('YYYY-MM-DD').split('-')[2]
    const sptdCurrent = moment(date).format('YYYY-MM-DD').split('-')[2]
    const sptm = moment(value).format('YYYY-MM-DD').split('-')[1]
    const error = 'Usia harus antara 17 hingga 55 tahun'

    if (((sptyCurrent - spty) < 16) || ((sptyCurrent - spty) > 54)) {
      callback(error)
    }

    if ((sptyCurrent - spty) === 16) {
      if (!((sptmCurrent - sptm) >= 6)) {
        callback(error)
      }
      if (!((sptdCurrent - sptd) >= 0)) {
        callback(error)
      }
      callback()
    }

    if ((sptyCurrent - spty) === 54) {
      if (((sptmCurrent - sptm) > 6)) {
        callback(error)
      }
      if (((sptdCurrent - sptd) > 0)) {
        callback(error)
      }
      callback()
    }
    callback()
  }

  const ktpValidator = (rule, value, callback) => {
    if ((/^[0-9]{16}$/.test(value))) {
      callback()
    } else if (value === '') {
      callback()
    } else if (value === undefined) {
      callback()
    } else {
      const error = 'Format Nomor KTP salah'
      callback(error)
    }
  }
  const validatePhone = (rule, value, callback) => {
    if ((/^08[0-9]{8,11}$/.test(value))) {
      callback()
    } else if (value === '') {
      callback()
    } else if (value === undefined) {
      callback()
    } else {
      const error = 'Format Nomor handphone salah'
      callback(error)
    }
  }
  const validateName = (rule, value, callback) => {
    if ((/^[a-zA-z]+[a-zA-Z ']{1,100}$/.test(value))) {
      callback()
    } else if (value === '') {
      callback()
    } else if (value === undefined) {
      callback()
    } else {
      const error = 'Nama harus diisi'
      callback(error)
    }
  }

  const provinceHandler = (changeValue) => {
    const localprovinceData = provinceData.find((item) => item.display_name === changeValue) || {}
    if (size(localprovinceData) > 0) {
      const id = get(localprovinceData, 'id')
      cityListRequest({
        query: {
          parent_id: id
        }
      })
      setFieldsValue({
        city: ''
      })
      setCityList([])
    }
  }

  const validatePostalCode = (rule, value, callback) => {
    if ((/^([0-9]){5,5}$/.test(value))) {
      callback()
    } else if (value === '') {
      callback()
    } else if (value === undefined) {
      callback()
    } else {
      const error = 'Format kode pos salah'
      callback(error)
    }
  }

  // TODO: formContainer

  return (
    <StyleWrapper>
      <Row className='rowStyle-parent' type='flex' justify='center' align='middle'>
        <Col span={22}>
          <Card className='cardContainer' title='Bukalapak Lead Generation Form'>
            <Form onSubmit={handleSubmit}>
              <Row type='flex' justify='space-between' gutter={10}>
                <Col span={10}>
                  <Form.Item label='Nama Tertanggung (Sesuai KTP)'>
                    {
                      getFieldDecorator('name', {
                        rules: [
                          {
                            required: true, message: 'Nama harus diisi'
                          },
                          {
                            validator: validateName
                          }
                        ]
                      })(
                        <Input />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Email Tertanggung'>
                    {
                      getFieldDecorator('email', {
                        rules: [
                          {
                            required: true, message: 'Email harus diisi'
                          }
                        ]
                      })(
                        <Input type='email' />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Tanggal Lahir Tertanggung'>
                    {
                      getFieldDecorator('dob', {
                        rules: [
                          {
                            type: 'object',
                            required: true
                          },
                          {
                            validator: checkDobValidator
                          }
                        ]
                      })(
                        <DatePicker />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Tempat Lahir Tertanggung (Kota)'>
                    {
                      getFieldDecorator('birth_place', {
                        rules: [
                          {
                            required: true,
                            message: 'Kota harus diisi'
                          }
                        ]
                      })(
                        <Select
                          showSearch
                          loading={BIRTH_POLICY_LOADER}
                          filterOption={(input, option) =>
                            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                        >
                          {
                            birthplace.length > 0 &&
                            birthplace.map((item, index) => <Option key={index} value={item.display_name}>{item.display_name}</Option>)
                          }
                        </Select>
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Nomor Identitas Tertanggung (KTP)'>
                    {
                      getFieldDecorator('ktp', {
                        rules: [
                          {
                            required: true,
                            message: 'Nomor KTP harus diisi'
                          },
                          {
                            validator: ktpValidator
                          }
                        ]
                      })(
                        <Input />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Alamat Saat Ini yang Diasuransikan'>
                    {
                      getFieldDecorator('address', {
                        rules: [
                          {
                            required: true,
                            message: 'Alamat lengkap harus diisi'
                          }
                        ]
                      })(
                        <Input />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Provinsi Tempat Tinggal Saat Ini'>
                    {
                      getFieldDecorator('province', {
                        rules: [
                          {
                            required: true,
                            message: 'Provinsi harus diisi'
                          }
                        ]
                      })(
                        <Select
                          showSearch
                          loading={PROVINCE_LIST_LOADER}
                          onChange={provinceHandler}
                          filterOption={(input, option) =>
                            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                        >
                          {
                            provinceData.length > 0 &&
                            provinceData.map((item, index) => <Option key={index} value={item.display_name}>{item.display_name}</Option>)
                          }
                        </Select>
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Tempat Tinggal Saat Ini'>
                    {
                      getFieldDecorator('city', {
                        rules: [
                          {
                            required: true,
                            message: 'Kota harus diisi'
                          }
                        ]
                      })(
                        <Select
                          showSearch
                          disabled={cityList.length === 0}
                          loading={CITY_LIST_LOADER}
                          onChange={provinceHandler}
                          filterOption={(input, option) =>
                            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                        >
                          {
                            cityList.length > 0 &&
                            cityList.map((item, index) => <Option key={index} value={item.display_name}>{item.display_name}</Option>)
                          }
                        </Select>
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Kode Pos Tempat Tinggal Saat Ini'>
                    {
                      getFieldDecorator('postal_code', {
                        rules: [
                          {
                            required: true,
                            message: 'Kode pos harus diisi'
                          },
                          {
                            validator: validatePostalCode
                          }
                        ]
                      })(
                        <Input />
                      )
                    }
                  </Form.Item>
                </Col>
                <Col span={10}>
                  <Form.Item label='Nomor Handphone'>
                    {
                      getFieldDecorator('phone_no', {
                        rules: [
                          {
                            required: true,
                            message: 'Nomor Ponsel harus diisi'
                          },
                          {
                            validator: validatePhone
                          }
                        ]
                      })(
                        <Input />
                      )
                    }
                  </Form.Item>
                </Col>
              </Row>
              <Row type='flex' justify='center'>
                <Col>
                  <Button
                    type='primary'
                    htmlType='submit'
                    loading={BUKALAPAK_QUOTE_LOADER}
                  >
                    Submit
                  </Button>
                </Col>
              </Row>
            </Form>
          </Card>
        </Col>
      </Row>
    </StyleWrapper>
  )
}

const WrappedformComponent = Form.create()(BukalapakLeadGeneration)

export default WrappedformComponent
