import { useTeleSalesContextValue } from '../../../context/TeleSalesContext'
import useServiceRequest from '../../../../hooks/useServiceRequest'
import actions from '../actions'

export function useResetState () {
  const [, dispatch] = useTeleSalesContextValue()
  const resetTeleSalesState = async (keys = []) => {
    await dispatch(actions.resetState(keys))
  }
  return [resetTeleSalesState]
}

export function useProvinceList () {
  const [{ provinceListData, provinceListStatus }, dispatch] = useTeleSalesContextValue()

  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.getProvinceList(payload))
  }
  return [{ provinceListData, provinceListStatus }, request]
}

